nodes.statement:
We consider linear regression models of the form
\begin{equation} \textcolor{black}{\ensuremath{Y}}= \textcolor{black}{\ensuremath{X}}\textcolor{black}{\ensuremath{\beta^*}} +\textcolor{black}{\ensuremath{\varepsilon}}
\end{equation}
with outcome $\textcolor{black}{\ensuremath{Y}}\in\mathbb{R}^n$, design matrix $\textcolor{black}{\ensuremath{X}}\in\mathbb{R}^{n\times p}$, regression vector $\textcolor{black}{\ensuremath{\beta^*}}\in\mathbb{R}^p$, and noise vector $\textcolor{black}{\ensuremath{\varepsilon}}\in\mathbb{R}^n$.

We thus consider estimators of the form
\begin{equation*}
  \ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}} \in \mathop{\mathrm{arg\,min}}_{\beta\in\mathbb{R}^p}\left\{\ensuremath{g}\big(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\beta}^2\big)+\operatorname{pen}(\ensuremath{\lambda},\beta)\right\}\,,
\end{equation*}
where $\ensuremath{g}$ is some real-valued link function, the mapping $\operatorname{pen}(\ensuremath{\lambda},\beta):\mathbb{R}^k\times\mathbb{R}^p\to\mathbb{R}$ accounts for the structural assumptions, and \ensuremath{\lambda}\ is a vector-valued tuning parameter.

More specifically, we consider assumptions on $\textcolor{black}{\ensuremath{\beta^*}}$ that are captured by (semi-)norms; the corresponding estimators then read 
\begin{equation} \ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}} \in \mathop{\mathrm{arg\,min}}_{\beta\in\mathbb{R}^p}\big\{\ensuremath{g}\big(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\beta}^2\big)+\sum_{j=1}^{\ensuremath{k}}\ensuremath{\lambda}_j\,\normqj{\ensuremath{M}_j\beta}\big\}\,.
\end{equation}

We then note that by the rank assumption on the matrices~$\ensuremath{M}_1,\dots,\ensuremath{M}_{\ensuremath{k}},$ there are projection matrices~$\ensuremath{\textcolor{black}{P_1,\dots,P_{\ensuremath{k}}}}\in\mathbb{R}^{p\times p}$ such that 
\begin{equation} \sum_{j=1}^{\ensuremath{k}}\textcolor{black}{P_j}\ensuremath{M_j}^{+}\ensuremath{M_j}=\operatorname{I}_{p\times p}\,.
\end{equation}

Consider fixed constants $\textcolor{black}{\ensuremath{c}}_1,\dots,\textcolor{black}{\ensuremath{c}}_{\ensuremath{k}}\in(0,\infty)$. With probability one, there is a tuning parameter $\ensuremath{\lambda}\equiv\ensuremath{\lambda}(\textcolor{black}{\ensuremath{c}}_1,\dots,\textcolor{black}{\ensuremath{c}}_{\ensuremath{k}})\in (0,\infty)^{\ensuremath{k}}$ such that
\begin{equation*}
\frac{\ensuremath{\lambda}}{2g'(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^2)}=\left(\textcolor{black}{\ensuremath{c}}_1\,\norm{(\textcolor{black}{\ensuremath{X}}  P_1\ensuremath{M}_1^{+})^\top \textcolor{black}{\ensuremath{\varepsilon}}}_{q_1}^*,\dots,\textcolor{black}{\ensuremath{c}}_{\ensuremath{k}}\,\norm{(\textcolor{black}{\ensuremath{X}}  P_{\ensuremath{k}}\ensuremath{M}_{\ensuremath{k}}^{+})^\top \textcolor{black}{\ensuremath{\varepsilon}}}_{q_{\ensuremath{k}}}^*\right)^\top.
\end{equation*}

For another abstract view on the theorem, we define a loss for any ${\ensuremath{\bf \textcolor{black}{\ensuremath{a}}}}\in(0,\infty)^{\ensuremath{k}}$ by
\begin{equation*}
  \textcolor{black}{\ensuremath{L_{\ensuremath{\bf \textcolor{black}{\ensuremath{a}}}}}}(\beta):=\frac{1}{n}\,\normtwo{\textcolor{black}{\ensuremath{X}}(\beta^*-\textcolor{black}{\beta})}^2 +\frac{1}{n}\sum_{j=1}^{\ensuremath{k}}\textcolor{black}{\ensuremath{a}}_j \,  \normqj{\ensuremath{M}_j \textcolor{black}{\beta}}\,.
\end{equation*}

Now, we observe that if $2(\textcolor{black}{\ensuremath{c}}_j-1)\,\normqjd{(\textcolor{black}{\ensuremath{X}}P_j\ensuremath{M}_j^{+})^\top\textcolor{black}{\ensuremath{\varepsilon}}}=\textcolor{black}{\ensuremath{a}}_j,$ choosing again $\textcolor{black}{\ensuremath{u}}=0.5$ in the initial functional yields
\begin{equation*}
  \textcolor{black}{\ensuremath{L_{\ensuremath{\bf \textcolor{black}{\ensuremath{a}}}}}}(\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}})\leq\Big(1+\max_{j\in\{1,\dots,\ensuremath{k}\}}\frac{4\,\normqjd{(\textcolor{black}{\ensuremath{X}}P_j\ensuremath{M}_j^{+})^\top\textcolor{black}{\ensuremath{\varepsilon}}}}{\textcolor{black}{\ensuremath{a}}_j}\Big) \min_{\textcolor{black}{\beta}\in\mathbb{R}^p}\textcolor{black}{\ensuremath{L_{\ensuremath{\bf \textcolor{black}{\ensuremath{a}}}}}}(\textcolor{black}{\beta})\,.
\end{equation*}

The lasso~\cite{Tibshirani96} is defined as
\begin{equation*}
  \ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}} \in \mathop{\mathrm{arg\,min}}_{\beta\in\mathbb{R}^p}\{\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\beta}^2+\ensuremath{\lambda}\,\normone{\beta}\}\,.
\end{equation*}

In the case $\textcolor{black}{\beta}=\beta^*,$ Inequality~\eqref{special2} does slightly better. Indeed, our results imply
\begin{equation*}
\frac{1}{n}\,\normtwo{\textcolor{black}{\ensuremath{X}}(\beta^*-\overline \beta)}^2 \le \frac 2 n\,\normsup{\textcolor{black}{\ensuremath{X}}  ^\top\textcolor{black}{\ensuremath{\varepsilon}}}\,   \normone{\beta^*}\,,
\end{equation*} 
which is smaller by a factor $2$ than the above right-hand side at $\textcolor{black}{\beta}=\beta^*.$

To provide a sense for the rates, we mention that if $	extcolor{black}{\ensuremath{\varepsilon}}_1,\dots,	extcolor{black}{\ensuremath{\varepsilon}}_n\stackrel{\mathclap{
ormalfont\mbox{\scriptsize iid}}}{\sim}\mathcal N(0,\sigma^2) $ and $(	extcolor{black}{\ensuremath{X}}^	op	extcolor{black}{\ensuremath{X}})_{jj}=n$ for all~$j\in\{1,\dots,p\}$, it holds that $\overline{\lambda}\approx \sigma\sqrt{n\log(p)}$ and $
ormtwo{	extcolor{black}{\ensuremath{X}}( eta^*-\overline  eta)}^2/n \lesssim \sigma\sqrt{\log(p)/n}\ 
ormone{ eta^*}$. ootnote{The wiggles indicate that we are interested only in the rough shapes and neglect constants, for example.}

The square-root lasso~\cite{Belloni11}  reads
\begin{equation*}
  \ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}} \in \mathop{\mathrm{arg\,min}}_{\beta\in\mathbb{R}^p}\left\{\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\beta}+\ensuremath{\lambda}\,\normone{\beta}\right\}\,.
\end{equation*}

The slope estimator~\cite{Bogdan15} can be written as
\begin{equation*}
  \ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}} \in \mathop{\mathrm{arg\,min}}_{\beta\in\mathbb{R}^p}\Big\{\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\beta}^2+\ensuremath{\lambda}\sum_{j=1}^p\omega_j|\beta|_{(j)}\Big\}\,,
\end{equation*}
where $|\beta|_{(j)}$ denotes the $j$th largest entry of $\beta$ in absolute value, $\omega_1\geq \dots \geq \omega_p>0$ is a non-increasing sequence of weights, and $\ensuremath{\lambda}>0$ is a tuning parameter.

The elastic net~\cite{Zou05} reads
\begin{equation*}
  \ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}} \in \mathop{\mathrm{arg\,min}}_{\beta\in\mathbb{R}^p}\left\{\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\beta}^2+\ensuremath{\lambda}_1\,\normone{\beta}+\ensuremath{\lambda}_2\,\normtwo{\beta}^2\right\}\,.
\end{equation*}

As an illustration, let us consider the group lasso with non-overlapping groups:
\begin{equation*}
  \ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}} \in \mathop{\mathrm{arg\,min}}_{\beta\in\mathbb{R}^p}\Big\{\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\beta}^2+\ensuremath{\lambda}\sum_{j=1}^{\ensuremath{k}}\, \normtwo{\beta_{G_j}}\Big\}\,.
\end{equation*}
Here, $G_1,\dots,G_{\ensuremath{k}}$ is a partition of $\{1,\dots,p\}$ and $(\beta_{G_j})_i:=\beta_i{\rm 1}\mskip -4,5mu{\rm l}\{i\in G_j\}.$ To put the estimator in  framework~\eqref{eq:estimator}, one can either generalize the estimator to incorporate possibly different tuning parameters for each group, set $\ensuremath{M}_j$ to~$(\ensuremath{M}_j)_{st}={\rm 1}\mskip -4,5mu{\rm l}\{s=t,s\in G_j\}$, and then choose a dominating tuning parameter, or one can directly extend our results (as mentioned earlier) to arbitrary norm penalties. In any case, the projection matrices/matrix equal the identity matrix, our standard tuning parameter  is $\overline{\lambda}=2\max_{l\in\{1,\dots,\ensuremath{k}\}}\,\normtwo{(\textcolor{black}{\ensuremath{X}}^\top\textcolor{black}{\ensuremath{\varepsilon}})_{G_l}}$, and the bound~\eqref{special2} gives  
\begin{equation*}
\frac{1}{n}\,\normtwo{\textcolor{black}{\ensuremath{X}}(\beta^*-\overline \beta)}^2 \le \frac{2}{n}\max_{l\in\{1,\dots,\ensuremath{k}\}}\,\normtwo{(\textcolor{black}{\ensuremath{X}}^\top\textcolor{black}{\ensuremath{\varepsilon}})_{G_l}} \sum_{j=1}^{\ensuremath{k}}\,\normtwo{\beta^*_{G_j}} \,.
\end{equation*}

Trend filtering~\cite{Kim09,Tibshirani14} reads
\begin{equation*}
  \ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}} \in \mathop{\mathrm{arg\,min}}_{\beta\in\mathbb{R}^p}\big\{\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\beta}^2+\ensuremath{\lambda}\, \normone{\ensuremath{M}\beta}\big\}\,,
\end{equation*}
where  for given $l\in\{1,2,\dots\}$, the matrix~$\ensuremath{M}\in\mathbb{R}^{p\times p}$ is defined as $\ensuremath{M}:=\underbrace{D\times \cdots \times D}_{l\text{~times}}$ with $D\in\mathbb{R}^{p\times p}$ given by
\begin{align*}
 D_{ij}:=\begin{cases}
\textcolor{black}{-}1&\text{~~~if~}i<p\text{~and~}i=j\\
\textcolor{white}{-}1&\text{~~~if~}i<p\text{~and~}i=j-1\\
\textcolor{white}{-}0&\text{~~~otherwise}
\end{cases}\,.
\end{align*}

We find $\overline{\lambda}=2\,
ormsup{\ensuremath{M}^+{}^	op	extcolor{black}{\ensuremath{\varepsilon}}}$, and~\eqref{special2} implies ootnote{Unlike assumed earlier, $\operatorname{Ker}(\ensuremath{M})
eq \{\mathbf 0_{p	imes p}\}$ in this example, but one can replace matrix $\ensuremath{M}$ by the invertible matrix $\ensuremath{M}+\epsilon\operatorname{I_{p	imes p}}$ and then take the limit $\epsilon	o 0.$}
 egin{equation*}
 rac{1}{n}\,
ormtwo{ eta^*-\overline  eta}^2 \le  rac 2 n\,
ormsup{\ensuremath{M}^+{}^	op	extcolor{black}{\ensuremath{\varepsilon}}}\,   
ormone{\ensuremath{M} eta^*}\,.
\end{equation*}

In the case $l=1,$ the estimator becomes 
\begin{equation*}
  \ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}} \in \mathop{\mathrm{arg\,min}}_{\beta\in\mathbb{R}^p}\big\{\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\beta}^2+\ensuremath{\lambda}\sum_{j=2}^p|\beta_j-\beta_{j-1}|\big\}\,,
\end{equation*}
which corresponds to the total variation~\cite{Rudin92} and fused lasso penalizations~\cite{Tibshirani05}. Moreover, one can check that the Moore-Penrose inverse of $\ensuremath{M}=D$ is then given by $D^+$ with entries
\begin{align*}
 D_{ij}^+:=\begin{cases}
~(j-p)/p&\text{~~~if~}i\leq j<p\\
~j/p&\text{~~~if~}i> j,~j<p\\
~0&\text{~~~if~}j=p
\end{cases}\,.
\end{align*}
We find  $\overline{\lambda}=2\,\normsup{D^+{}^\top\textcolor{black}{\ensuremath{\varepsilon}}}$ and the corresponding bound
\begin{equation*}
\frac{1}{n}\,\normtwo{\beta^*-\overline \beta}^2 \le \frac 2 n\,\normsup{D^+{}^\top\textcolor{black}{\ensuremath{\varepsilon}}}\,   \normone{D\beta^*}\,.
\end{equation*}

Note that (see \cite[Section~2.2]{vanderVaart96} for maximal inequalities that can be used for the last line)
\begin{align*}
\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\overline \beta}
= &\ \normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\textcolor{black}{\ensuremath{\beta^*}}+\textcolor{black}{\ensuremath{X}}\textcolor{black}{\ensuremath{\beta^*}}-\textcolor{black}{\ensuremath{X}}\overline \beta}\\
\le&\ \normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\textcolor{black}{\ensuremath{\beta^*}}}+\normtwo{\textcolor{black}{\ensuremath{X}}\textcolor{black}{\ensuremath{\beta^*}}-\textcolor{black}{\ensuremath{X}}\overline \beta}\\
\le& \ \normtwo{\textcolor{black}{\ensuremath{\varepsilon}}}+\sqrt{\frac{2\,\normsup{\textcolor{black}{\ensuremath{X}}^\top\textcolor{black}{\ensuremath{\varepsilon}}}\,\normone{\textcolor{black}{\ensuremath{\beta^*}}}}{n}}\sqrt{n}\\
\lesssim& \ \sqrt{n}+\sqrt{\frac{\log(p)\ \normone{\textcolor{black}{\ensuremath{\beta^*}}}}{\sqrt n}}\sqrt{n}
\end{align*}
and similarly 
\begin{align*}
\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\overline \beta}
\gtrsim& \ \sqrt{n}-\sqrt{\frac{\log(p)\ \normone{\textcolor{black}{\ensuremath{\beta^*}}}}{\sqrt n}}\sqrt{n}\,.
\end{align*}
Thus, as long as $\normone{\textcolor{black}{\ensuremath{\beta^*}}}=o(\sqrt n/\log (p)),$ it holds that $\overline{\lambda}\approx \normsup{\textcolor{black}{\ensuremath{X}}^\top\textcolor{black}{\ensuremath{\varepsilon}}}/\,\normtwo{\textcolor{black}{\ensuremath{\varepsilon}}}\approx\sqrt{\log(p)}.$

For any
$\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}, \ensuremath{\tilde\beta^{\ensuremath{\lambda}}}  \in \mathop{\mathrm{arg\,min}}_{\beta\in\mathbb{R}^p} \big\{g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\beta}^{2})+\sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\ensuremath{M}_j\beta}\big\}$ and $\alpha \in [0,1],$  it holds that $\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}=\textcolor{black}{\ensuremath{X}} \ensuremath{\tilde\beta^{\ensuremath{\lambda}}}$ and
\begin{equation*}
\alpha\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}+(1-\alpha)\ensuremath{\tilde\beta^{\ensuremath{\lambda}}} \in \mathop{\mathrm{arg\,min}}_{\beta\in\mathbb{R}^p} \big\{g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\beta}^{2})+\sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\ensuremath{M}_j\beta}\big\}\,.
\end{equation*}

Let $\mathbb{R}^{\ensuremath{k}}$ be  equipped with the Euclidean norm, and $\mathbb{R}$ be equipped with the  absolute value norm. Then, the function
\begin{align*}
(0,\infty)^{\ensuremath{k}} &\to \mathbb{R}\\
  \lambda&\mapsto g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^{2})
\end{align*}
and the function
\begin{align*}
(0,\infty)^{\ensuremath{k}} &\to \mathbb{R}\\
  \lambda&\mapsto \normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^{2}
\end{align*}
are both continuous.

The case $\alpha\in\{0,1\}$ is straightforward, so that we consider a given $\alpha\in(0,1).$ We first show that $\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}=\textcolor{black}{\ensuremath{X}} \ensuremath{\tilde\beta^{\ensuremath{\lambda}}}$. 




Since the function $\alpha\mapsto g(\,\normtwo{\alpha}^2)$ is strictly convex by assumption, it follows for any vectors $a,\tilde a\in\mathbb{R}^n$ that
\begin{align*}
g(\,\normtwo{\alpha a+(1-\alpha)\tilde a}^{2})\le \alpha g(\,\normtwo{a}^{2})+(1-\alpha)g(\,\normtwo{\tilde a}^{2})
\end{align*}
with strict inequality if $a\neq \tilde a$.  Using this with $a=\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}} \ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}$ and $\tilde a= \textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\tilde\beta^{\ensuremath{\lambda}}},$ and invoking the convexity of the norms~$\normqj{\cdot},$ we find
\begin{align*}
&g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\big(\alpha \ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}+(1-\alpha)\ensuremath{\tilde\beta^{\ensuremath{\lambda}}}\big)}^{2})+\sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\ensuremath{M}_j\big(\alpha \ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}+(1-\alpha)\ensuremath{\tilde\beta^{\ensuremath{\lambda}}}\big)}\\
=&g(\,\normtwo{\alpha(\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}})+(1-\alpha)(\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\tilde\beta^{\ensuremath{\lambda}}})}^{2})+\sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\alpha \ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}+(1-\alpha)\ensuremath{M}_j\ensuremath{\tilde\beta^{\ensuremath{\lambda}}}}\\
\leq&\alpha g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^{2})+(1-\alpha)g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\tilde\beta^{\ensuremath{\lambda}}}}^{2})+\alpha\sum_{j=1}^{\ensuremath{k}} \lambda_j \,\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}+(1-\alpha)\sum_{j=1}^{\ensuremath{k}}\lambda_j \, \normqj{\ensuremath{M}_j\ensuremath{\tilde\beta^{\ensuremath{\lambda}}}}\\
=&\alpha \Big(g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^{2})+\sum_{j=1}^{\ensuremath{k}} \lambda_j \,\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}\Big)+(1-\alpha)\Big(g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\tilde\beta^{\ensuremath{\lambda}}}}^{2})+\sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\ensuremath{M}_j\ensuremath{\tilde\beta^{\ensuremath{\lambda}}}}\Big)
\end{align*}
with strict inequality if $\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}\neq \textcolor{black}{\ensuremath{X}} \ensuremath{\tilde\beta^{\ensuremath{\lambda}}}.$ 
Moreover, we note that 
\begin{equation*}
\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}, \ensuremath{\tilde\beta^{\ensuremath{\lambda}}}  \in \mathop{\mathrm{arg\,min}}_{\beta\in\mathbb{R}^p} \big\{g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\beta}^{2})+\sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\ensuremath{M}_j\beta}\big\}  
\end{equation*}
implies 
\begin{align*}
g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\tilde\beta^{\ensuremath{\lambda}}}}^{2})+\sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\ensuremath{M}_j\ensuremath{\tilde\beta^{\ensuremath{\lambda}}}}=g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^{2})+\sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}\,.
\end{align*}
Combining the results yields
\begin{align*}
&g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\big(\alpha \ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}+(1-\alpha)\ensuremath{\tilde\beta^{\ensuremath{\lambda}}}\big)}^{2})+\sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\ensuremath{M}_j\big(\alpha \ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}+(1-\alpha)\ensuremath{\tilde\beta^{\ensuremath{\lambda}}}\big)}\\
\leq&g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^{2})+\sum_{j=1}^{\ensuremath{k}} \lambda_j \,\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}
\end{align*}
with strict inequality if $\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}\neq \textcolor{black}{\ensuremath{X}} \ensuremath{\tilde\beta^{\ensuremath{\lambda}}}.$ Using again that 
\begin{equation*}
  \ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}} \in \mathop{\mathrm{arg\,min}}_{\beta\in\mathbb{R}^p} \left\{g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\beta}^{2})+\sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\ensuremath{M}_j\beta}\right\}\,,
\end{equation*}
we find that the above inequality is actually an equality, so that 
\begin{equation*}
\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}=\textcolor{black}{\ensuremath{X}}\ensuremath{\tilde\beta^{\ensuremath{\lambda}}}\,.
\end{equation*}
and
\begin{equation*}
\alpha\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}+(1-\alpha)\ensuremath{\tilde\beta^{\ensuremath{\lambda}}}\in \mathop{\mathrm{arg\,min}}_{\beta\in\mathbb{R}^p} \bigg\{g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\beta}^{2})+\sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\ensuremath{M}_j\beta}\bigg\}\,
\end{equation*}
as desired.

To show that the function $\lambda\mapsto g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^{2})$ is continuous, we first show that the function 
\begin{align*}
\mathbb{R}^{\ensuremath{k}} &\to \mathbb{R} \\
\lambda &\mapsto g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^{2})+\sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}
\end{align*} 
is continuous.\\
For this, we show the continuity at any  fixed  $\lambda\in(0,\infty)^{\ensuremath{k}}$. Given an $\epsilon>0,$ define  $m:=2\max_{1\le j\le \ensuremath{k}}\left\{\frac{g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}}^2)}{\lambda_j}\right\}$ and $\delta:= \min_{1\le j\le \ensuremath{k}}\frac{\lambda_j}{2}\wedge \frac{\epsilon}{\sqrt{k}m},$ where $\wedge$ denotes the minimum. Consider now an arbitrary $\lambda'\in(0,\infty)^{\ensuremath{k}}$ with $\normtwo{\lambda-\lambda'} < \delta.$ 

As a next step,  note that Criterion~\eqref{eq:estimator} implies
\begin{equation*}
  g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^2)+\sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}} \leq   g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}}^2)\,.
\end{equation*}
In particular, since the function $g$ is non-negative on $[0,\infty)$ by assumption, it holds that
\begin{equation*}
 \sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}} \leq   g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}}^2)\,.
\end{equation*}
Thus, we have 
\begin{equation*}
 \lambda_j\,\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}} \leq   g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}}^2) \text{~~for $j\in\{1,2,\dots,\ensuremath{k}\}$} \,.
\end{equation*}
Hence, if $\lambda_j>0,$ it holds that
\begin{equation} \normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}} \le \frac{g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}}^2)}{\lambda_j }\text{~~for $j\in\{1,2,\dots,\ensuremath{k}\}$} \,.
\end{equation}
Also note that by Criterion~\eqref{eq:estimator}, it holds that
\begin{align*}
g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^2)+\sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}&\le g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}'}}}^2)+\sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}'}}}
\end{align*}
and
\begin{align*}
g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}'}}}^2)+\sum_{j=1}^{\ensuremath{k}}\lambda'_j\,\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}'}}}&\le g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^2)+\sum_{j=1}^{\ensuremath{k}}\lambda'_j\,\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}\,.
\end{align*}
Rearranging these two inequalities, we obtain
\begin{align*}
g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^2)+\sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}-g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}'}}}^2)-\sum_{j=1}^{\ensuremath{k}}\,\lambda'_j\,\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}'}}} &\le \sum_{j=1}^{\ensuremath{k}}(\lambda_j-\lambda'_j)\,\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}'}}}\
\end{align*}
and
\begin{align*}
g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^2)+\sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}-g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}'}}}^2)-\sum_{j=1}^{\ensuremath{k}}\,\lambda'_j\,\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}'}}} &\ge \sum_{j=1}^{\ensuremath{k}}(\lambda_j-\lambda'_j)\,\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}\,.
\end{align*}
By H\"older's inequality and Inequality~\eqref{eq:continuous1}, it holds that
\begin{align*}
\sum_{j=1}^{\ensuremath{k}}(\lambda_j-\lambda'_j)\,\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}&\ge - \,\normone{\lambda-\lambda'}\max_{1\le j\le \ensuremath{k}}\big\{\,\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}\big\} \\
&\ge -\,\normone{\lambda-\lambda'}\max_{1\le j\le \ensuremath{k}}\left\{\frac{g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}}^2)}{\lambda_j}\right\}
\end{align*}
and similarly
\begin{align*}
\sum_{j=1}^{\ensuremath{k}}(\lambda_j-\lambda'_j)\,\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}'}}}&\le \normone{\lambda-\lambda'}\max_{1\le j\le \ensuremath{k}}\left\{\frac{g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}}^2)}{\lambda'_j}\right\}.
\end{align*}
Now trivially, $\max_{1\le j\le \ensuremath{k}}\left\{\frac{g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}}^2)}{\lambda_j}\right\}\leq m$. Moreover,
\begin{align*}
\max_{1\le j\le \ensuremath{k}}\left\{\frac{g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}}^2)}{\lambda'_j}\right\}\leq \max_{1\le j\le \ensuremath{k}}\left\{\frac{g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}}^2)}{\lambda_j-\normtwo{\lambda-\lambda'}}\right\}\leq m
\end{align*}
by definition of $m$ and $\delta.$ Using this and again the definition of $\delta$, we then find
\begin{align*}
\Big | g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^2)+\sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}-g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}'}}}^2)-\sum_{j=1}^{\ensuremath{k}}\lambda'_j\,\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}'}}} \Big|<\epsilon\,.
\end{align*}
This implies the desired continuity.

Now we show that function  $\lambda \mapsto g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^2)$ is continuous.  We proceed with contradiction. Thus, we assume there exist $\lambda' \in (0,\infty)^{\ensuremath{k}}$ and $\epsilon_0 >0,$ so that for any $\delta>0,$ there exists $\lambda \in (0,\infty)^{\ensuremath{k}}$ satisfying
\begin{align*}
\normtwo{\lambda-\lambda'}<\delta \quad \text{and}\quad  \Big|\,g(\, \normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^2)-g(\, \normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}'}}}^2)\Big|\ge \epsilon_0\,.
\end{align*}
We note that by Lemma~\ref{re:convexity}, the value of $g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^2)$ does not depend on the specific  choice of the estimator~$\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}.$ 
Since $x\mapsto g(x)$ is strictly increasing, there exists $\epsilon'_0\equiv \epsilon'_0(\epsilon_0)>0$ such that 
\begin{equation} \Big|\,\normtwo{\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^2-\normtwo{\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}'}}}^2\Big|>\epsilon'_0\, .
\end{equation} 
Define the set $B:=\left\{\beta\in\mathbb{R}^p: \big|\,\normtwo{\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}'}}}^2-\normtwo{\textcolor{black}{\ensuremath{X}}\beta}^2\big|>\epsilon'_0\right\}$. It follows directly that $\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}'}}\notin B$, and due to Inequality~\eqref{eq:continuous2} above, it follows that $\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}\in B.$ Let $\eta>0$ be arbitrary. Invoking Criterion~\eqref{eq:estimator} and the continuity of the objective function (note that taking minima does not affect the continuity), we obtain
\begin{align*}
&g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^2)+\sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}\\
=&\min_{\beta\in B}\big\{g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\beta}^2)+\sum_{j=1}^{\ensuremath{k}}
\lambda_j\,\normqj{\ensuremath{M}_j\beta}\big\}\\
\geq &\min_{\beta\in B}\big\{g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\beta}^2)+\sum_{j=1}^{\ensuremath{k}}
\lambda'_j\,\normqj{\ensuremath{M}_j\beta}\big\}-\eta
\end{align*}
if $\delta$ is sufficiently small. Moreover, using $\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}'}}\notin B$ and again the continuity, it holds for $\delta$ sufficiently small that
\begin{align*}
& \min_{\beta\in B}\big\{g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\beta}^2)+\sum_{j=1}^{\ensuremath{k}}
\lambda'_j\,\normqj{\ensuremath{M}_j\beta}\big\}\\
> & \min_{\beta\in \mathbb{R}^p}\big\{g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\beta}^2)+\sum_{j=1}^{\ensuremath{k}}
\lambda'_j\,\normqj{\ensuremath{M}_j\beta}\big\}+\xi\\
\geq & \min_{\beta\in \mathbb{R}^p}\big\{g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\beta}^2)+\sum_{j=1}^{\ensuremath{k}}
\lambda_j\,\normqj{\ensuremath{M}_j\beta}\big\}+\xi/2
\end{align*}
for a $\xi \equiv \xi (\lambda',\epsilon'_0)>0$. Choosing $\eta=\xi/4,$ we find
\begin{align*}
& \min_{\beta\in \mathbb{R}^p}\big\{g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\beta}^2)+\sum_{j=1}^{\ensuremath{k}}
\lambda_j\,\normqj{\ensuremath{M}_j\beta}\big\}\\
> & \min_{\beta\in \mathbb{R}^p}\big\{g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\beta}^2)+\sum_{j=1}^{\ensuremath{k}}
\lambda_j\,\normqj{\ensuremath{M}_j\beta}\big\}+\xi/4,
\end{align*}
which is a contradiction and thus concludes the proof of the continuity of the function $\ensuremath{\lambda}\mapsto\ensuremath{g}(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^2)$. The continuity of the function $\ensuremath{\lambda}\mapsto\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^2$ then follows from the assumption that the link function~\ensuremath{g}\ is continuous and increasing. This concludes the proof of the lemma.

Since $\textcolor{black}{\ensuremath{Y}}\neq \bold{0}_{n}$ with probability one, we assume $\textcolor{black}{\ensuremath{Y}}\neq \bold{0}_{n}$ in the following. 

We then show that 
\begin{equation*}
\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}>0\,.
\end{equation*}
We do this by contradiction, that is, we assume
\begin{equation*}
\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}=0\,.
\end{equation*}
This implies
\begin{equation} \textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}=\bold{0}_n\,.
\end{equation}
Since  $\beta\mapsto g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\beta}^2)$ is convex, the subdifferential $\partial _\beta g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\beta}^2)\Big|_{\beta=\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}$ exists. Thus, the KKT conditions imply 
\begin{equation*}
\bold{0}_p\in\ \partial _\beta g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\beta}^2)\Big|_{\beta=\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}+\sum_{j=1}^{\ensuremath{k}} \lambda_j\partial_\beta\,\normqj{\ensuremath{M}_j\beta}\Big|_{\beta=\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}\,,
\end{equation*}
which implies by the chain rule
\begin{equation*}
\bold{0}_p\in\partial_x g(x)\big|_{x=\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}} \ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^2}\big(-2\textcolor{black}{\ensuremath{X}}^\top (\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}})\big)+\sum_{j=1}^{\ensuremath{k}} \lambda_j\partial_\beta\,\normqj{\ensuremath{M}_j\beta}\big|_{\beta=\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}\,.
\end{equation*}
Plugging Equality~\eqref{eq:assumption} into this display yields
\begin{equation*}
\bold{0}_p\in \sum_{j=1}^{\ensuremath{k}} \lambda_j\partial_\beta\,\normqj{\ensuremath{M}_j\beta}\big|_{\beta=\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}\,.
\end{equation*}
This means that the vector~\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}\ minimizes the function $\beta\mapsto \sum_{j=1}^{\ensuremath{k}} \lambda_j\,\normqj{\ensuremath{M}_j\beta}.$ However, since $\ensuremath{\lambda}_1,\dots,\ensuremath{\lambda}_{\ensuremath{k}}>0$, and by assumption on the matrices $\ensuremath{M}_1,\dots,\ensuremath{M}_{\ensuremath{k}},$ this mapping is a norm and is thus minimized only at ${\bf 0}_p.$ Consequently, $\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}={\bf 0}_p.$ However,  Equality~\eqref{eq:assumption} then gives 
\begin{equation*}
\textcolor{black}{\ensuremath{Y}}=\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}=\textcolor{black}{\ensuremath{X}}\bold{0}_p=\bold{0}_n\,,
\end{equation*}
which contradicts $\textcolor{black}{\ensuremath{Y}}\neq\bold{0}_n.$ Thus, $\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}\neq \bold{0}_n,$ and it follows that  $\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^2\neq 0$. 

Since the function $x\mapsto g(x)$ is continuously differentiable on $(0,\infty)$ with strictly positive derivative, we finally obtain
\begin{equation*}
g'(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^2)> 0
\end{equation*}
as desired.

The proof consists of three steps.  First, we show that the solution equals zero if the tuning parameters are large enough. Second, we show that if one element of the tuning parameter is sufficiently large, increasing that element does not affect the estimator. Finally, we use these results to show the existence of suitable tuning parameters.

Let us start with some notation. For each $j\in\{1,\dots,\ensuremath{k}\},$ we define the set  $A_j\subset \{1,2,\dots,p\}$ such that for any $u
\in A_j,$ the $u$th row of $\ensuremath{M}_j$ is not zero, that is, $A_j:=\{u\in\{1,\dots,p\}:\max_{v\in\{1,\dots,p\}}|(\ensuremath{M}_{j})_{uv}|>0\}.$ By assumption on the sequence  $\ensuremath{M}_1,\dots,\ensuremath{M}_{\ensuremath{k}}$, it holds that $\bigcup_{j=1}^{\ensuremath{k}}A_j=\{1,\dots,p\}.$ For $j\in\{1,\dots,k\},$ define the vector $(\textcolor{black}{\ensuremath{X}}^\top \textcolor{black}{\ensuremath{Y}})^j\in\mathbb{R}^p$  via $(\textcolor{black}{\ensuremath{X}}^\top \textcolor{black}{\ensuremath{Y}})^j_i:=(\textcolor{black}{\ensuremath{X}}^\top \textcolor{black}{\ensuremath{Y}})_i{\rm 1}\mskip -4,5mu{\rm l}\{i\in A_j\}\,,$ and set $m:=\max_{j\in\{1,\dots,\ensuremath{k}\}}2 g'(\,\normtwo{\textcolor{black}{\ensuremath{Y}}}^2)\,\normqjd{(\textcolor{black}{\ensuremath{X}}^\top \textcolor{black}{\ensuremath{Y}})^j}\vee 1,$ where $\vee$ denotes the maximum. 

The three mentioned steps now read in detail:
\begin{enumerate}
\item Show that for any $\lambda\in[m,\infty)^{\ensuremath{k}}$, it holds that
\begin{align*}
\{\bold{0}_p\}=\mathop{\mathrm{arg\,min}}_{\beta\in\mathbb{R}^p}\big\{g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\beta}^2)+\sum_{j=1}^{\ensuremath{k}} \lambda_j\,\normqj{\ensuremath{M}_j\beta}\big\}\,.
\end{align*}

\item Show that $\textcolor{black}{\ensuremath{X}}\ensuremath{\widehat \beta}^{\tilde{\ensuremath{\lambda}}}=\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}$ if  $\tilde\lambda,  \lambda \in(0,\infty)^{\ensuremath{k}}$  satisfy
\begin{align*}
\tilde\lambda_j
> \lambda_j =m &\text{~~~ if } j\in B \\ 
\tilde\lambda_j=\lambda_j & \text{~~~ if }  j\notin B
\end{align*}
for a non-empty subset $B \subset \{1,2,\dots,\ensuremath{k}\}$.




\item  Show that with probability one, there exists a vector $\lambda\in(0,\infty)^{\ensuremath{k}}$ that satisfies
 \begin{equation} \frac{\lambda_j}{2g'(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^2)}=\textcolor{black}{\ensuremath{c}}_j \,\normqjd{(\textcolor{black}{\ensuremath{X}} P_j \ensuremath{M}_j^{+})^\top\textcolor{black}{\ensuremath{\varepsilon}}}
 \end{equation}
 for all $j\in\{1,\dots,\ensuremath{k}\}$.
\end{enumerate}


Step 1:
We first show that 
\begin{equation*}
\bold{0}_p\in \mathop{\mathrm{arg\,min}}_{\beta\in\mathbb{R}^p} \big\{ g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\beta}^2)+\sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\ensuremath{M}_j\beta}\big\}\,
\end{equation*}
implies
\begin{equation*}
\{\bold{0}_p\}=\mathop{\mathrm{arg\,min}}_{\beta\in\mathbb{R}^p} \big\{ g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\beta}^2)+\sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\ensuremath{M}_j\beta}\big\}\,.
\end{equation*}
Assume for a $\lambda\in[m,\infty)^{\ensuremath{k}}$, it holds that
\begin{equation*}
\bold{0}_p\in \mathop{\mathrm{arg\,min}}_{\beta\in\mathbb{R}^p} \big\{ g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\beta}^2)+\sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\ensuremath{M}_j\beta}\big\}\,.
\end{equation*}
then by Lemma~\ref{re:convexity}, for any $\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}\in\mathop{\mathrm{arg\,min}}_{\beta\in\mathbb{R}^p} \big\{ g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\beta}^2)+\sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\ensuremath{M}_j\beta}\big\}\,,$ it holds that $\textcolor{black}{\ensuremath{X}} \ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}=\bold{0}_n\,.$
Hence, by assumption on the matrices $\ensuremath{M}_1,\dots,\ensuremath{M}_{\ensuremath{k}},$ it holds for any $\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}\neq {\bf 0}_p,$
\begin{align*}
&g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^2)+\sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}\\
=&g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}}^2)+\sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}\\
> &g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}}^2)+\sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\ensuremath{M}_j{\bf 0}_p}\\
=&g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}{\bf 0}_p}^2)+\sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\ensuremath{M}_j{\bf 0}_p}\,.
\end{align*}
This contradicts $\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}\in\mathop{\mathrm{arg\,min}}_{\beta\in\mathbb{R}^p} \big\{ g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\beta}^2)+\sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\ensuremath{M}_j\beta}\big\}\,,$ and thus, $\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}={\bf 0}_p.$  Thus,
\begin{equation*}
\{\bold{0}_p\}=\mathop{\mathrm{arg\,min}}_{\beta\in\mathbb{R}^p} \big\{ g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\beta}^2)+\sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\ensuremath{M}_j\beta}\big\}\,
\end{equation*}
as desired.
It is left to show that for any vector $\lambda\in[m,\infty)^{\ensuremath{k}}$, it holds that
\begin{equation*}
\bold{0}_p\in \mathop{\mathrm{arg\,min}}_{\beta\in\mathbb{R}^p} \big\{ g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\beta}^2)+\sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\ensuremath{M}_j\beta}\big\}\,.
\end{equation*}
By the KKT conditions, we have to show that there are vectors $\kappa(j)\in\partial_{\beta}\,\normqj{\ensuremath{M}_j\beta}\Big|_{\beta=\bold{0}_p}$ such that 
\begin{equation} -2g'(\,\normtwo{\textcolor{black}{\ensuremath{Y}}}^2)\textcolor{black}{\ensuremath{X}}^\top \textcolor{black}{\ensuremath{Y}}+\sum_{j=1}^{\ensuremath{k}}\lambda_j \kappa(j)=\bold{0}_p\,.
\end{equation}
 Define $\tilde A_1:=A_1, \tilde A_j:=A_j\setminus \{A_1,\dots,A_{j-1}\} \text{ for } j=2,\dots,\ensuremath{k}$. In particular, $\tilde A_j\subset A_j$, the $\tilde A_j$'s are disjoint, and $\bigcup_{j=1}^{\ensuremath{k}} \tilde A_j=\{1,\dots,p\}$. 
With this notation, we need to show that for any $v\in\tilde A_j$ and $j\in\{1,\dots,\ensuremath{k}\}$, it holds that 
\begin{align*}
-2g'(\,\normtwo{\textcolor{black}{\ensuremath{Y}}}^2)(\textcolor{black}{\ensuremath{X}}^\top \textcolor{black}{\ensuremath{Y}})_v+\sum_{j=1}^{\ensuremath{k}}\lambda_j \kappa(j)_v=0\,.
\end{align*}
Define the vector $\kappa(j)$ for $j\in\{1,\dots,\ensuremath{k}\}$ via
\begin{align*}
\kappa(j)_v:=\begin{cases}
\frac{2g'(\,\normtwo{\textcolor{black}{\ensuremath{Y}}}^2)(\textcolor{black}{\ensuremath{X}}^\top \textcolor{black}{\ensuremath{Y}})^j_v}{\lambda_j} &\text{ if } v\in \tilde A_j \\ 
0 & \text{ if } v\notin \tilde A_j \,.
\end{cases}
\end{align*}
Since $\tilde A_j\subset A_j$ and $\tilde A_j$'s are disjoint, we find for all $j\in\{1,\dots,\ensuremath{k}\}$ and $v\in \tilde A_j,$ that
\begin{align*}
-2g'(\,\normtwo{\textcolor{black}{\ensuremath{Y}}}^2)(\textcolor{black}{\ensuremath{X}}^\top \textcolor{black}{\ensuremath{Y}})_v+\sum_{j=1}^{\ensuremath{k}}\lambda_j \kappa(j)_v=-2g'(\,\normtwo{\textcolor{black}{\ensuremath{Y}}}^2)(\textcolor{black}{\ensuremath{X}}^\top \textcolor{black}{\ensuremath{Y}})^j_v+\lambda_j \kappa(j)_v\,.
\end{align*}
By definition of the vectors $\kappa(j)$ for $j\in\{1,\dots,\ensuremath{k}\},$ we thus have
\begin{align*}
-2g'(\,\normtwo{\textcolor{black}{\ensuremath{Y}}}^2)(\textcolor{black}{\ensuremath{X}}^\top \textcolor{black}{\ensuremath{Y}})^j_v+\lambda_j \kappa(j)_v=0\,,
\end{align*}
which implies
\begin{align*}
-2g'(\,\normtwo{\textcolor{black}{\ensuremath{Y}}}^2)(\textcolor{black}{\ensuremath{X}}^\top \textcolor{black}{\ensuremath{Y}})_v+\sum_{j=1}^{\ensuremath{k}}\lambda_j \kappa(j)_v=0\,.
\end{align*}
Since  $\lambda_j\ge m\ge 2g'(\,\normtwo{\textcolor{black}{\ensuremath{Y}}}^2)\,\normqjd{ (\textcolor{black}{\ensuremath{X}}^\top \textcolor{black}{\ensuremath{Y}})^j}$, it also follows by taking the dual norm on both sides that
\begin{equation} \normqjd{\kappa(j)}\le \frac{2g'(\,\normtwo{\textcolor{black}{\ensuremath{Y}}}^2)\,\normqjd{(\textcolor{black}{\ensuremath{X}}^\top \textcolor{black}{\ensuremath{Y}})^j}}{\lambda_j}\leq 1\,,
\end{equation}
and hence, $\kappa(j)\in\partial_{\beta}\, \normqj{\ensuremath{M}_j\beta}\Big|_{\beta=\bold{0}_p}$ for all $j\in\{1,\dots,\ensuremath{k}\}$\,. So we get
\begin{equation*}
\bold{0}_p\in\mathop{\mathrm{arg\,min}}_{\beta\in\mathbb{R}^p} \big\{ g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\beta}^2)+\sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\ensuremath{M}_j\beta}\big\}\,.
\end{equation*}
as desired.
We conclude that 
\begin{equation*}
\{\bold{0}_p\}=\mathop{\mathrm{arg\,min}}_{\beta\in\mathbb{R}^p} \big\{ g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\beta}^2)+\sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\ensuremath{M}_j\beta}\big\}\,.
\end{equation*}

Step 2: 
Consider a pair of vectors $\lambda, \tilde \lambda\in (0,\infty)^{\ensuremath{k}},$ that satisfy $\tilde \lambda_j> \lambda_j=m$ for $j\in B$ and $\tilde\lambda_j=\lambda_j$ for $j\in \{1,\dots,\ensuremath{k}\}\setminus B.$
For $\lambda$, fix a solution
\begin{equation*}
\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}\in \mathop{\mathrm{arg\,min}}_{\beta\in\mathbb{R}_p} \big\{ g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\beta})+\sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\ensuremath{M}_j\beta}\big\}
\end{equation*}
with corresponding subdifferentials $\kappa(j)\in\partial_{\beta} \,\normqj{\ensuremath{M}_j\beta}\Big|_{\beta=\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}$ that satisfy the KKT conditions
\begin{align*}
-2g'(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^2)\textcolor{black}{\ensuremath{X}}^\top (\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}})+\sum_{j=1}^{\ensuremath{k}} \lambda_j \kappa(j)=\bold{0}_p\,.
\end{align*}
We first need to show that 
\begin{equation*}
\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}\in \mathop{\mathrm{arg\,min}}_{\beta\in\mathbb{R}_p} \big\{ g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\beta})+\sum_{j=1}^{\ensuremath{k}}\tilde\lambda_j\,\normqj{\ensuremath{M}_j\beta}\big\}\,.
\end{equation*}
By the KKT conditions, we have to show that there are the vectors $\tilde\kappa(j)\in\partial_{\beta}\, \normqj{\ensuremath{M}_j\beta}\Big|_{\beta=\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}$ such that
\begin{align*}
-2g'(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^2)\textcolor{black}{\ensuremath{X}}^\top (\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}})+\sum_{j=1}^{\ensuremath{k}}\tilde \lambda_j \tilde\kappa(j)=\bold{0}_p\,.
\end{align*}
Define $\tilde \kappa(j)$ for $j\in\{1,\dots,\ensuremath{k}\}$ via
\begin{align*}
\tilde\kappa(j):=\frac{\lambda_j}{\tilde \lambda_j}\kappa(j) \,.
\end{align*}
Plugging this into the previous display yields
\begin{align*}
-2g'(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^2)\textcolor{black}{\ensuremath{X}}^\top (\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}})+\sum_{j=1}^{\ensuremath{k}}\tilde \lambda_j \tilde \kappa(j)=-2g'(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^2)\textcolor{black}{\ensuremath{X}}^\top( \textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}})+\sum_{j=1}^{\ensuremath{k}}\lambda_j \kappa_j\,.
\end{align*}
Therefore,  it holds that
\begin{align*}
-2g'(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^2)\textcolor{black}{\ensuremath{X}}^\top (\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}})+\sum_{j=1}^{\ensuremath{k}}\tilde \lambda_j \tilde \kappa(j)=\bold{0}_p\,.
\end{align*}
Moreover, by definition of $\tilde \kappa(j)$ and Inequality~\eqref{eq:boundedlambda}, we have that 
\begin{equation*}
\normqjd{\tilde\kappa(j)}=\frac{\lambda_j}{\tilde \lambda_j}\,\normqjd{\kappa(j)} \leq \normqjd{\kappa(j)}\le 1\,,
\end{equation*}
for all $j\in B$. So,  $\tilde \kappa(j)\in\partial_{\beta}\, \normqj{\ensuremath{M}_j\beta}\Big|_{\beta=\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}$ for any $j\in\{1,\dots,\ensuremath{k}\}$.
Hence, it holds that
\begin{equation*}
\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}\in \mathop{\mathrm{arg\,min}}_{\beta\in\mathbb{R}^p} \big\{ g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\beta})+\sum_{j=1}^{\ensuremath{k}}\tilde\lambda_j\,\normqj{(\ensuremath{M}_j\beta)^j}\big\}\,.
\end{equation*}





This gives $\textcolor{black}{\ensuremath{X}}\ensuremath{\widehat \beta}^{\tilde{\ensuremath{\lambda}}}=\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}$  by  Lemma~\ref{re:convexity}.\vspace{2mm}

Step 3: Finally, we show the existence of a $\lambda\in (0,\infty)^{\ensuremath{k}}$ that satisfies Equality~\eqref{re:oracleexistence}. For this, we define
\begin{equation*}
  a:=m\wedge \left(2\ensuremath{g}'(\,\normtwo{\textcolor{black}{\ensuremath{Y}}}^2)\min_{j\in\{1,\dots,\ensuremath{k}\}} \textcolor{black}{\ensuremath{c}}_j\,\norm{(\textcolor{black}{\ensuremath{X}} P_j\ensuremath{M}_j^{+})^\top\textcolor{black}{\ensuremath{\varepsilon}}}_{q_j}^*\right)\,.
\end{equation*}
By assumption on the noise~$\textcolor{black}{\ensuremath{\varepsilon}},$ it holds that $a>0$ with probability one. Next, we consider the function 
\begin{align*}
f: [a,m]^{\ensuremath{k}}&\to \mathbb{R}^{\ensuremath{k}}\\
\lambda&\mapsto f(\ensuremath{\lambda}):=2g'(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\widehat \beta}^{\lambda}}^2)\left(\textcolor{black}{\ensuremath{c}}_1\,\norm{(\textcolor{black}{\ensuremath{X}} P_1\ensuremath{M}_1^{+})^\top\textcolor{black}{\ensuremath{\varepsilon}}}_{q_1}^*,\dots,\textcolor{black}{\ensuremath{c}}_k\,\norm{(\textcolor{black}{\ensuremath{X}} P_k\ensuremath{M}_k^{+})^\top\textcolor{black}{\ensuremath{\varepsilon}}}_{q_k}^*\right)^\top.
\end{align*}
Note first that $\ensuremath{g}(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^2)\leq \ensuremath{g}(\,\normtwo{\textcolor{black}{\ensuremath{Y}}}^2)$ by definition of the estimator~\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}.  Hence, since  $\ensuremath{g}'$ is non-increasing, we find
\begin{align*}
 \min_{\lambda\in[a,m]^{\ensuremath{k}}}  \min_{j\in\{1,\dots,\ensuremath{k}\}} f(\lambda)_j\geq a\,.
\end{align*}
Note also that $[a,m]^{\ensuremath{k}}$ is compact and that $f$ is continuous by Lemmas~\ref{re:functions} and~\ref{re:nonzero} and the assumption that $g'(x)$  is continuous on $(0,\infty)$. It therefore holds that 
\begin{equation*}
\sup_{\lambda\in[a,m]^{\ensuremath{k}}} \normsup{f(\lambda)} \leq b
\end{equation*}
for some  $b\in(0,\infty).$ Using this and Step 2, we find that the function $f$ and the function





\begin{align*}
h: [a,b\vee m]^{\ensuremath{k}}&\to [a,b\vee m]^{\ensuremath{k}}\\
\lambda&\mapsto h(\ensuremath{\lambda}):=2g'(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\widehat \beta}^{\lambda}}^2)\left(\textcolor{black}{\ensuremath{c}}_1\,\norm{(\textcolor{black}{\ensuremath{X}} P_1\ensuremath{M}_1^{+})^\top\textcolor{black}{\ensuremath{\varepsilon}}}_{q_1}^*,\dots,\textcolor{black}{\ensuremath{c}}_k\,\norm{(\textcolor{black}{\ensuremath{X}} P_k\ensuremath{M}^{+}_k)^\top\textcolor{black}{\ensuremath{\varepsilon}}}_{q_k}^*\right)^\top
\end{align*}
have the same images, that is,
\begin{align*}
\left\{y: y=f(\lambda),\lambda\in[a,m]^{\ensuremath{k}} \right\}=\left\{y: y=h(\lambda),\lambda\in[a,b\vee m]^{\ensuremath{k}} \right\}\,.
\end{align*}
The function  $h$ is continuous. Moreover, $[a,b\vee m]^{\ensuremath{k}}$ is a compact and convex subset of~$\mathbb{R}^k$. We can thus apply  Brouwer's fixed-point theorem to deduce that 
\begin{align*}
\lambda=2g'(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\widehat \beta}^{\lambda}}^2)\left(\textcolor{black}{\ensuremath{c}}_1\,\norm{(\textcolor{black}{\ensuremath{X}} P_1\ensuremath{M}_1^{+})^\top\textcolor{black}{\ensuremath{\varepsilon}}}_{q_1}^*,\dots,\textcolor{black}{\ensuremath{c}}_k\,\norm{(\textcolor{black}{\ensuremath{X}} P_k\ensuremath{M}_k^{+})^\top\textcolor{black}{\ensuremath{\varepsilon}}}_{q_k}^*\right)^\top
\end{align*}
for a vector  $\lambda\in [a,b\vee m]^{\ensuremath{k}}$. According to Lemma~\ref{re:nonzero}, it holds  that $g'(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^2)>0$ with probability one, so that
 \begin{equation*}
   \frac{\ensuremath{\lambda}}{2g'(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\widehat \beta}^{\lambda}}^2)}=\left(\textcolor{black}{\ensuremath{c}}_1\,\norm{(\textcolor{black}{\ensuremath{X}}  P_1\ensuremath{M}_1^{+})^\top \textcolor{black}{\ensuremath{\varepsilon}}}_{q_1}^*,\dots, \textcolor{black}{\ensuremath{c}}_k\,\norm{(\textcolor{black}{\ensuremath{X}}  P_{\ensuremath{k}}\ensuremath{M}_{\ensuremath{k}}^{+})^\top \textcolor{black}{\ensuremath{\varepsilon}}}_{q_{\ensuremath{k}}}^*\right)^\top
  \end{equation*}
as desired.

Consider the function
\begin{align*}
\mathbb{R}^p&\to \mathbb{R}\\
\beta&\mapsto f(\beta):=g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\beta}^2)+\sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\ensuremath{M}_j\beta}\,.
\end{align*}
According to our assumptions on the link function and the penalties, $f$ is convex, and $\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}$ minimizes $f.$  
Therefore, ${\bf 0}_p\in\partial f(\beta)|_{\beta=\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}.$ 
Subdifferentials are additive, so that we can write $\partial f(\beta)|_{\beta=\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}$ as a sum of subdifferentials of the individual parts of $f.$ In particular, we can decompose ${\bf 0}_p\in\partial f(\beta)|_{\beta=\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}$ as 
\begin{equation*}
  {\bf 0}_p= \frac{\partial}{\partial \beta}g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\beta}^2)\Big|_{\beta=\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}+\sum_{j=1}^{\ensuremath{k}}\ensuremath{\lambda}_j\kappa_j\,,
\end{equation*}
where $\kappa_j\in\partial\{\alpha\mapsto \normqj{M_{j}\alpha}\}|_{\alpha=\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}$ and, using the assumption that the function $g$ is differentiable on $(0,\infty),$
\begin{equation*}
 \frac{\partial}{\partial \beta}g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\beta}^2)\Big|_{\beta=\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}=-2 g'(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^2)\big(\textcolor{black}{\ensuremath{X}}^{\top}(\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}})\big)\,.
\end{equation*}
Adding the pieces together implies for all $\beta\in\mathbb{R}^p$
\begin{equation*}
  0={\bf 0}_p^\top(\textcolor{black}{\beta}-\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}})=\big(-2 g'(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^2)\big(\textcolor{black}{\ensuremath{X}}^{\top}(\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}})\big)+\sum_{j=1}^{\ensuremath{k}}\ensuremath{\lambda}_j\kappa_j\big)^\top(\textcolor{black}{\beta}-\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}})\,.
\end{equation*}
Now, $\kappa_j\in\partial\{\alpha\mapsto \normqj{M_{j}\alpha}\}|_{\alpha=\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}},$ which means by the definition of subdifferentials for convex functions that  for all $\textcolor{black}{\beta}\in \mathbb{R}^p$
\begin{equation*}
\normqj{\ensuremath{M}_{j}\textcolor{black}{\beta}}\ge \normqj{\ensuremath{M}_{j}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}+\inprod{\kappa_j}{\textcolor{black}{\beta}-\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}\,,
\end{equation*}
which is equivalent to
\begin{align*}
\normqj{\ensuremath{M}_j\textcolor{black}{\beta}}-\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}\ge \kappa_j^\top (\textcolor{black}{\beta}-\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}})\,.
\end{align*}
Combining with the above yields
\begin{align*}
&-2g'(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^2) \big(\textcolor{black}{\ensuremath{X}}^\top(\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}})\big)^\top(\textcolor{black}{\beta}-\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}})
+\sum_{j=1}^{\ensuremath{k}}\lambda_j\big(\,\normqj{ \ensuremath{M}_j \textcolor{black}{\beta}}-\normqj{ \ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}\big)\,\geq\,0 \,. 
\end{align*}
According to the model~\eqref{eq:model}, we can replace $\textcolor{black}{\ensuremath{Y}}$ with  $\textcolor{black}{\ensuremath{X}}\beta^*+\textcolor{black}{\ensuremath{\varepsilon}}$ to obtain
\begin{align*}
&\big(\textcolor{black}{\ensuremath{X}}^\top(\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}})\big)^\top(\textcolor{black}{\beta}-\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}})\\
 =&\big(\textcolor{black}{\ensuremath{X}}^\top(\textcolor{black}{\ensuremath{X}}\beta^*+\textcolor{black}{\ensuremath{\varepsilon}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}})\big)^\top(\textcolor{black}{\beta}-\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}})\\
 = &(\textcolor{black}{\ensuremath{X}}(\beta^*-\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}))^\top \textcolor{black}{\ensuremath{X}}(\textcolor{black}{\beta}-\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}})+\textcolor{black}{\ensuremath{\varepsilon}}^\top \textcolor{black}{\ensuremath{X}}(\textcolor{black}{\beta}-\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}})\\
= &(\textcolor{black}{\ensuremath{X}}(\beta^*-\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}))^\top \textcolor{black}{\ensuremath{X}}(\beta^*-\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}+\textcolor{black}{\beta}-\beta^*)+\textcolor{black}{\ensuremath{\varepsilon}}^\top \textcolor{black}{\ensuremath{X}}(\textcolor{black}{\beta}-\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}})\\
 =& \,\normtwo{\textcolor{black}{\ensuremath{X}}(\beta^*-\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}})}^2+ (\textcolor{black}{\ensuremath{X}}(\beta^*-\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}))^\top \textcolor{black}{\ensuremath{X}}(\textcolor{black}{\beta}-\beta^*)+ \textcolor{black}{\ensuremath{\varepsilon}}^\top \textcolor{black}{\ensuremath{X}}(\textcolor{black}{\beta}-\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}})\,.



\end{align*}
Now, we note that for any $\textcolor{black}{\ensuremath{u}}>0,$
  \begin{equation*}   
 (\textcolor{black}{\ensuremath{X}}(\beta^*-\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}))^\top \textcolor{black}{\ensuremath{X}}(\textcolor{black}{\beta}-\beta^*)
\geq -\textcolor{black}{\ensuremath{u}}\,\normtwo{\textcolor{black}{\ensuremath{X}}(\beta^*-\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}})}^2-\frac{\normtwo{\textcolor{black}{\ensuremath{X}}(\textcolor{black}{\beta}-\beta^*)}^2}{4\textcolor{black}{\ensuremath{u}}}\,.
  \end{equation*}
Using this in the foregoing display and consolidating gives us
  \begin{equation*}
    (\textcolor{black}{\ensuremath{X}}^\top(\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}))^\top(\textcolor{black}{\beta}-\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}})\geq \,(1-\textcolor{black}{\ensuremath{u}})\,\normtwo{\textcolor{black}{\ensuremath{X}}(\beta^*-\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}})}^2-\frac{\normtwo{\textcolor{black}{\ensuremath{X}}(\textcolor{black}{\beta}-\beta^*)}^2}{4\textcolor{black}{\ensuremath{u}}} + \textcolor{black}{\ensuremath{\varepsilon}}^\top \textcolor{black}{\ensuremath{X}}(\textcolor{black}{\beta}-\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}})\,.
  \end{equation*}
Plugging this back into the earlier display yields, noting that $\ensuremath{g}'$ is a positive function by assumption,
\begin{multline*}
 -2g'(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^2)\big((1-\textcolor{black}{\ensuremath{u}})\, \normtwo{\textcolor{black}{\ensuremath{X}}(\beta^*-\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}})}^2-\frac{\normtwo{\textcolor{black}{\ensuremath{X}}(\textcolor{black}{\beta}-\beta^*)}^2}{4\textcolor{black}{\ensuremath{u}}} +\langle \textcolor{black}{\ensuremath{\varepsilon}}, \textcolor{black}{\ensuremath{X}}(\textcolor{black}{\beta}-\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}})\rangle\big)\\
+\sum_{j=1}^{\ensuremath{k}}\lambda_j\big(\,\normqj{ \ensuremath{M}_j \textcolor{black}{\beta}}-\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}\big)\ge 0\,.
\end{multline*}
Rearranging this inequality, we obtain
\begin{multline*}
2g'(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^2)\big((1-\textcolor{black}{\ensuremath{u}})\, \normtwo{\textcolor{black}{\ensuremath{X}}(\beta^*-\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}})}^2+\langle \textcolor{black}{\ensuremath{\varepsilon}}, \textcolor{black}{\ensuremath{X}}(\textcolor{black}{\beta}-\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}})\rangle \big)\\ \le \sum_{j=1}^{\ensuremath{k}}\lambda_j\big(\,\normqj{ \ensuremath{M}_j \textcolor{black}{\beta}}-\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}\big)+2g'(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^2)\,\frac{\normtwo{\textcolor{black}{\ensuremath{X}}(\textcolor{black}{\beta}-\beta^*)}^2}{4\textcolor{black}{\ensuremath{u}}}\,.
\end{multline*}
According to Lemma~\ref{re:nonzero},  we can divide both sides by $2g'(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^2)$, so that
\begin{multline*}
 (1-\textcolor{black}{\ensuremath{u}})\,\normtwo{\textcolor{black}{\ensuremath{X}}(\beta^*-\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}})}^2+\langle \textcolor{black}{\ensuremath{\varepsilon}}, \textcolor{black}{\ensuremath{X}}(\textcolor{black}{\beta}-\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}})\rangle \\
\le \sum_{j=1}^{\ensuremath{k}}\frac{\lambda_j}{2g'(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^2)}\big(\,\normqj{ \ensuremath{M}_j \textcolor{black}{\beta}}-\normqj{ \ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}\big)+\frac{\normtwo{\textcolor{black}{\ensuremath{X}}(\textcolor{black}{\beta}-\beta^*)}^2}{4\textcolor{black}{\ensuremath{u}}}
\end{multline*}
and
\begin{multline*}
(1-\textcolor{black}{\ensuremath{u}})\, \normtwo{\textcolor{black}{\ensuremath{X}}(\beta^*-\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}})}^2 \\
\le \langle \textcolor{black}{\ensuremath{\varepsilon}}, \textcolor{black}{\ensuremath{X}}(\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}-\textcolor{black}{\beta})\rangle+ \sum_{j=1}^{\ensuremath{k}}\frac{\lambda_j}{2g'(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^2)}(\,\normqj{ \ensuremath{M}_j \textcolor{black}{\beta}}-\,\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}})+\frac{\normtwo{\textcolor{black}{\ensuremath{X}}(\textcolor{black}{\beta}-\beta^*)}^2}{4\textcolor{black}{\ensuremath{u}}}
\end{multline*}
with probability one.
Recall that by Equation~\eqref{eq:partition},  the vector $\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}-\textcolor{black}{\beta}$ can be rewritten as
\begin{align*}
\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}-\textcolor{black}{\beta}=\sum_{j=1}^{\ensuremath{k}} P_{j} \ensuremath{M}_j^+\ensuremath{M}_{j} (\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}-\textcolor{black}{\beta})\,.
\end{align*}
So we can reorganize the inner product $\langle \textcolor{black}{\ensuremath{\varepsilon}}, \textcolor{black}{\ensuremath{X}}(\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}-\textcolor{black}{\beta}) \rangle$ according to
\begin{align*}
 \langle \textcolor{black}{\ensuremath{\varepsilon}}, \textcolor{black}{\ensuremath{X}}(\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}-\textcolor{black}{\beta})\rangle
&= \langle \textcolor{black}{\ensuremath{\varepsilon}}, \textcolor{black}{\ensuremath{X}} \sum_{j=1}^{\ensuremath{k}} P_{j} \ensuremath{M}_j^+\ensuremath{M}_{j} (\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}-\textcolor{black}{\beta}) \rangle\\
&= \sum_{j=1}^{\ensuremath{k}} \langle \textcolor{black}{\ensuremath{\varepsilon}}, \textcolor{black}{\ensuremath{X}}P_{j} \ensuremath{M}_j^+\ensuremath{M}_{j} (\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}-\textcolor{black}{\beta})\rangle\\
&=\sum_{j=1}^{\ensuremath{k}}  \langle  (\textcolor{black}{\ensuremath{X}}  P_j\ensuremath{M}_{j}^+)^\top\textcolor{black}{\ensuremath{\varepsilon}}, \ensuremath{M}_{j} (\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}-\textcolor{black}{\beta})\rangle\,.
\end{align*}
Plugging this into the previous inequality yields
\begin{align*}
&(1-\textcolor{black}{\ensuremath{u}})\,\normtwo{\textcolor{black}{\ensuremath{X}}(\beta^*-\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}})}^2 \\      
\le & \sum_{j=1}^{\ensuremath{k}}\big( \langle  (\textcolor{black}{\ensuremath{X}}   P_j \ensuremath{M}_j^{+})^\top\textcolor{black}{\ensuremath{\varepsilon}}, \ensuremath{M}_j (\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}-\textcolor{black}{\beta})\rangle+\frac{\lambda_j}{2g'(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^2)}(\,\normqj{\ensuremath{M}_j \textcolor{black}{\beta}}-\,\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}})\big)+\frac{\normtwo{\textcolor{black}{\ensuremath{X}}(\textcolor{black}{\beta}-\beta^*)}^2}{4\textcolor{black}{\ensuremath{u}}}\,.
\end{align*}
Using H\"older's Inequality, we can rewrite the first term in the second line according to
\begin{align*}
 \langle  (\textcolor{black}{\ensuremath{X}}  P_j \ensuremath{M}_j^{+})^\top\textcolor{black}{\ensuremath{\varepsilon}}, \ensuremath{M}_j (\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}-\textcolor{black}{\beta})\rangle \le \normqjd{(\textcolor{black}{\ensuremath{X}}   P_j \ensuremath{M}_j^{+})^\top\textcolor{black}{\ensuremath{\varepsilon}}}\,\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}-\ensuremath{M}_j \textcolor{black}{\beta}}\,.
\end{align*}
Plugging this back into the previous display gives
\begin{multline*}
(1-\textcolor{black}{\ensuremath{u}})\,\normtwo{\textcolor{black}{\ensuremath{X}}(\beta^*-\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}})}^2 
\leq  \sum_{j=1}^{\ensuremath{k}}\big(\,\normqjd{(\textcolor{black}{\ensuremath{X}}  P_j \ensuremath{M}_j^{+})^\top\textcolor{black}{\ensuremath{\varepsilon}}}\,\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}-\ensuremath{M}_j \textcolor{black}{\beta}}\\+\frac{\lambda_j}{2g'(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^2)}(\,\normqj{\ensuremath{M}_j \textcolor{black}{\beta}}-\,\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}})\big)
+\frac{\normtwo{\textcolor{black}{\ensuremath{X}}(\textcolor{black}{\beta}-\beta^*)}^2}{4\textcolor{black}{\ensuremath{u}}}\,.
\end{multline*}
We can modify this further by applying the triangle inequality and by reorganizing the terms. We find
\begin{align*}
&(1-\textcolor{black}{\ensuremath{u}})\,\normtwo{\textcolor{black}{\ensuremath{X}}(\beta^*-\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}})}^2 \\ 
\le & \sum_{j=1}^{\ensuremath{k}}\big(\,\normqjd{(\textcolor{black}{\ensuremath{X}}  P_j \ensuremath{M}_j^{+})^\top\textcolor{black}{\ensuremath{\varepsilon}}}(\,\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}+\,\normqj{\ensuremath{M}_j \textcolor{black}{\beta}})+\frac{\lambda_j}{2g'(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^2)}(\,\normqj{\ensuremath{M}_j \textcolor{black}{\beta}}-\,\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}})\big)\\
&+\frac{\normtwo{\textcolor{black}{\ensuremath{X}}(\textcolor{black}{\beta}-\beta^*)}^2}{4\textcolor{black}{\ensuremath{u}}}\\
=& \sum_{j=1}^{\ensuremath{k}}\big(\,\normqjd{(\textcolor{black}{\ensuremath{X}}  P_j \ensuremath{M}_j^{+})^\top\textcolor{black}{\ensuremath{\varepsilon}}}+\frac{\lambda_j}{2g'(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^2)}\big)\,\normqj{\ensuremath{M}_j \textcolor{black}{\beta}}\\
& +\sum_{j=1}^{\ensuremath{k}}\big(\,\normqjd{(\textcolor{black}{\ensuremath{X}} P_j \ensuremath{M}_j^{+})^\top\textcolor{black}{\ensuremath{\varepsilon}}}-\frac{\lambda_j}{2g'(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^2)}\big)\,\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}+\frac{\normtwo{\textcolor{black}{\ensuremath{X}}(\textcolor{black}{\beta}-\beta^*)}^2}{4\textcolor{black}{\ensuremath{u}}}\,.
\end{align*}
We now set $\lambda$ according to Lemma~\ref{re:existence}. It then holds that\begin{align*}
\frac{\lambda_j}{2g'(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^2)}= \textcolor{black}{\ensuremath{c}}_j\,\normqjd{(\textcolor{black}{\ensuremath{X}}  P_j\ensuremath{M}_j^{+})^\top\textcolor{black}{\ensuremath{\varepsilon}}}
\end{align*}
 for all $j\in\{1,\dots,\ensuremath{k}\}.$
 Then it follows that








 \begin{multline*}
(1-\textcolor{black}{\ensuremath{u}})\,\normtwo{\textcolor{black}{\ensuremath{X}}(\beta^*-\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}})}^2\\
 \le \sum_{j=1}^{\ensuremath{k}}(1+\textcolor{black}{\ensuremath{c}}_j)\, \normqjd{(\textcolor{black}{\ensuremath{X}}  P_j\ensuremath{M}_j^{+})^\top\textcolor{black}{\ensuremath{\varepsilon}}} \,  \normqj{\ensuremath{M}_j \textcolor{black}{\beta}}+\sum_{j=1}^{\ensuremath{k}}(1-\textcolor{black}{\ensuremath{c}}_j)\, \normqjd{(\textcolor{black}{\ensuremath{X}}  P_j\ensuremath{M}_j^{+})^\top\textcolor{black}{\ensuremath{\varepsilon}}} \,  \normqj{\ensuremath{M}_j \ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}+\frac{\normtwo{\textcolor{black}{\ensuremath{X}}(\beta^*-\textcolor{black}{\beta})}^2}{4\textcolor{black}{\ensuremath{u}}}\,.
\end{multline*}





To bring this into the standard form, assuming $\textcolor{black}{\ensuremath{u}}<1,$ we finally divide both sides by $(1-\textcolor{black}{\ensuremath{u}})n$ and find
\begin{multline*}
\frac{1}{n}\,\normtwo{\textcolor{black}{\ensuremath{X}}(\beta^*-\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}})}^2\le \frac{1}{n}\sum_{j=1}^{\ensuremath{k}}\frac{1+\textcolor{black}{\ensuremath{c}}_j}{1-\textcolor{black}{\ensuremath{u}}}\,  \normqjd{(\textcolor{black}{\ensuremath{X}}  P_j\ensuremath{M}_j^{+})^\top\textcolor{black}{\ensuremath{\varepsilon}}}  \, \normqj{\ensuremath{M}_j \textcolor{black}{\beta}}\\+\frac{1}{n}\sum_{j=1}^{\ensuremath{k}}\frac{1-\textcolor{black}{\ensuremath{c}}_j}{1-\textcolor{black}{\ensuremath{u}}}\, \normqjd{(\textcolor{black}{\ensuremath{X}}  P_j\ensuremath{M}_j^{+})^\top\textcolor{black}{\ensuremath{\varepsilon}}} \,  \normqj{\ensuremath{M}_j \ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}+\frac{1}{4\textcolor{black}{\ensuremath{u}}(1-\textcolor{black}{\ensuremath{u}})n}\,\normtwo{\textcolor{black}{\ensuremath{X}}(\beta^*-\textcolor{black}{\beta})}^2\,.
\end{multline*}
Since $\textcolor{black}{\beta}\in\mathbb{R}^p$ and $\textcolor{black}{\ensuremath{u}}\in(0,1)$ were arbitrary, this inequality provides us with the desired statement.

Moreover, we note that 
\begin{equation*}
\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}, \ensuremath{\tilde\beta^{\ensuremath{\lambda}}}  \in \mathop{\mathrm{arg\,min}}_{\beta\in\mathbb{R}^p} \big\{g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\beta}^{2})+\sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\ensuremath{M}_j\beta}\big\}  
\end{equation*}
implies 
\begin{align*}
g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\tilde\beta^{\ensuremath{\lambda}}}}^{2})+\sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\ensuremath{M}_j\ensuremath{\tilde\beta^{\ensuremath{\lambda}}}}=g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^{2})+\sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}\,.
\end{align*}

Combining the results yields
\begin{align*}
&g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\big(\alpha \ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}+(1-\alpha)\ensuremath{\tilde\beta^{\ensuremath{\lambda}}}\big)}^{2})+\sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\ensuremath{M}_j\big(\alpha \ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}+(1-\alpha)\ensuremath{\tilde\beta^{\ensuremath{\lambda}}}\big)}\\
\leq&g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^{2})+\sum_{j=1}^{\ensuremath{k}} \lambda_j \,\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}
\end{align*}
with strict inequality if $\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}\neq \textcolor{black}{\ensuremath{X}} \ensuremath{\tilde\beta^{\ensuremath{\lambda}}}.$

Using again that 
\begin{equation*}
  \ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}} \in \mathop{\mathrm{arg\,min}}_{\beta\in\mathbb{R}^p} \left\{g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\beta}^{2})+\sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\ensuremath{M}_j\beta}\right\}\,,
\end{equation*}
we find that the above inequality is actually an equality, so that 
\begin{equation*}
\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}=\textcolor{black}{\ensuremath{X}}\ensuremath{\tilde\beta^{\ensuremath{\lambda}}}\,.
\end{equation*}
and
\begin{equation*}
\alpha\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}+(1-\alpha)\ensuremath{\tilde\beta^{\ensuremath{\lambda}}}\in \mathop{\mathrm{arg\,min}}_{\beta\in\mathbb{R}^p} \bigg\{g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\beta}^{2})+\sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\ensuremath{M}_j\beta}\bigg\}\,
\end{equation*}
as desired.

To show that the function $\lambda\mapsto g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^{2})$ is continuous, we first show that the function 
\begin{align*}
\mathbb{R}^{\ensuremath{k}} &\to \mathbb{R} \\
\lambda &\mapsto g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^{2})+\sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}
\end{align*} 
is continuous.\\

As a next step,  note that Criterion~\eqref{eq:estimator} implies
\begin{equation*}
  g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}-\textcolor{black}{\ensuremath{X}}\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}^2)+\sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}} \leq   g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}}^2)\,.
\end{equation*}
In particular, since the function $g$ is non-negative on $[0,\infty)$ by assumption, it holds that
\begin{equation*}
 \sum_{j=1}^{\ensuremath{k}}\lambda_j\,\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}} \leq   g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}}^2)\,.
\end{equation*}
Thus, we have 
\begin{equation*}
 \lambda_j\,\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}} \leq   g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}}^2) \text{~~for $j\in\{1,2,\dots,\ensuremath{k}\}$} \,.
\end{equation*}
Hence, if $\lambda_j>0,$ it holds that
\begin{equation} \normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}} \le \frac{g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}}^2)}{\lambda_j }\text{~~for $j\in\{1,2,\dots,\ensuremath{k}\}$} \,.
\end{equation}

By H\"older's inequality and Inequality~\eqref{eq:continuous1}, it holds that
\begin{align*}
\sum_{j=1}^{\ensuremath{k}}(\lambda_j-\lambda'_j)\,\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}&\ge - \,\normone{\lambda-\lambda'}\max_{1\le j\le \ensuremath{k}}\big\{\,\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}}}}\big\} \\
&\ge -\,\normone{\lambda-\lambda'}\max_{1\le j\le \ensuremath{k}}\left\{\frac{g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}}^2)}{\lambda_j}\right\}
\end{align*}
and similarly
\begin{align*}
\sum_{j=1}^{\ensuremath{k}}(\lambda_j-\lambda'_j)\,\normqj{\ensuremath{M}_j\ensuremath{\ensuremath{\widehat \beta}^{\ensuremath{\lambda}'}}}&\le \normone{\lambda-\lambda'}\max_{1\le j\le \ensuremath{k}}\left\{\frac{g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}}^2)}{\lambda'_j}\right\}.
\end{align*}
Now trivially, $\max_{1\le j\le \ensuremath{k}}\left\{\frac{g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}}^2)}{\lambda_j}\right\}\leq m$.

Moreover,
\begin{align*}
\max_{1\le j\le \ensuremath{k}}\left\{\frac{g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}}^2)}{\lambda'_j}\right\}\leq \max_{1\le j\le \ensuremath{k}}\left\{\frac{g(\,\normtwo{\textcolor{black}{\ensuremath{Y}}}^2)}{\lambda_j-\normtwo{\lambda-\lambda'}}\right\}\leq m
\end{align*}
by definition of $m$ and $\delta.$ Using this and again the definition of $\delta$, we then find
\begin{align*}
